package dev.zomboidmelee.boxing;
import dev.zomboidmelee.boxing.CombatChecks18.*;import dev.zomboidmelee.boxing.Checks16.*;import net.neoforged.neoforge.network.PacketDistributor;import net.minecraft.world.phys.Vec3;
public class DirectionChecks24{
 static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 public static class P extends Actor{double px,pz;P(double x,double z){px=x;pz=z;}public double getX(){return px;}public double getZ(){return pz;}public double distanceToSqr(Zombie v){return (v.x-px)*(v.x-px)+(v.z-pz)*(v.z-pz);}public double distanceToSqr(Vec3 v){return (v.x-px)*(v.x-px)+v.y*v.y+(v.z-pz)*(v.z-pz);}}
 public static class FootPose extends Pose{float lastZ;public void scale(float x,float y,float z){lastZ=z;}}
 public static class Tracking{Object p,v;Tracking(Object p,Object v){this.p=p;this.v=v;}public Object getEntity(){return p;}public Object getTarget(){return v;}}
 static Zombie fall(P p,float facing){Zombie z=new Zombie(p.w);z.yBodyRot=facing;Stomp18.recoil(z,p);return z;}
 static double x(Object v){return R.num(R.get(v,"x"));}static double z(Object v){return R.num(R.get(v,"z"));}
 public static void main(String[]args){P front=new P(0,4);Zombie a=fall(front,0);Fall24.Direction da=Fall24.direction(a);ok(da!=null&&da.back(),"front impact falls onto back");ok(Math.abs(da.yaw()-180)<1,"front impact direction is away from attacker");Object h=Stomp18.head(a);ok(z(h)<a.z-.90&&Fall24.tilt(a)==1,"head follows backward fall");
 P rear=new P(0,0);Zombie b=fall(rear,0);Fall24.Direction db=Fall24.direction(b);ok(db!=null&&!db.back()&&Math.abs(db.yaw())<1,"rear impact falls forwards");h=Stomp18.head(b);ok(z(h)>b.z+.90&&Fall24.tilt(b)==-1,"forward fall reverses root tilt and head position");
 P side=new P(-2,2);Zombie c=fall(side,0);h=Stomp18.head(c);ok(x(h)>.90&&Math.abs(z(h)-c.z)<.02,"side blow lands in actual side direction");ok(Math.abs(Fall24.turn(c))<=90.1,"no unnecessary full body spin");
 int cues=PacketDistributor.cues.size();Stomp18.recoil(c,new P(3,2));ok(PacketDistributor.cues.size()==cues&&x(Stomp18.head(c))>.90,"later hits do not reroll existing fall orientation");Fall24.tracking(new Tracking(front,c));ok(PacketDistributor.cues.size()==cues+1&&((Heavy18)PacketDistributor.cues.getLast()).entityId()==1,"late tracker receives zombie direction");
 P stomp=new P(2.3,2.95);b.w.entities.put(50,stomp);stomp.eye=new Vec3(2.3,1.6,2.95);stomp.look=new Vec3(-2.3,-1.25,0).scale(1/Math.hypot(2.3,1.25));ok(((java.util.Optional<?>)R.call(b.getBoundingBox(),"clip",stomp.eye,stomp.eye.add(stomp.look.scale(3)))).isEmpty(),"fixture ray misses body but aims at displaced head");ok(Stomp18.headAim(stomp,b)&&Stomp18.stompAim(stomp,b),"directional head outside torso box remains stompable");stomp.w.wall=true;ok(!Stomp18.stompAim(stomp,b),"head target still respects a solid wall");
 stomp.w.wall=false;stomp.w.entities.put(1,b);Zombie standing=new Zombie(stomp.w);standing.x=-.4;standing.z=2.95;stomp.w.entities.put(2,standing);net.minecraft.client.Minecraft mc=net.minecraft.client.Minecraft.INSTANCE;mc.player=stomp;mc.level=stomp.w;mc.hitResult=new net.minecraft.world.phys.EntityHitResult(standing,new Vec3(.1,.4,2.95));ok(R.call(StompTarget21.target(mc),"getEntity")==b,"fallen head in front of standing zombie takes the closer ray hit");mc.hitResult=new net.minecraft.world.phys.EntityHitResult(standing,new Vec3(2,.4,2.95));ok(StompTarget21.target(mc)==mc.hitResult,"closer standing entity still occludes fallen head");
 int action=Fall24.encode(270,true);c.w.client=true;c.data.putLong("boxing24_fall_code",1001);Fall24.receive(c,action);ok(Fall24.direction(c).back()&&Math.abs(Fall24.direction(c).yaw()-270)<.1,"client follows received orientation, not local persistent data");cues=PacketDistributor.cues.size();Fall24.record(c,side);ok(PacketDistributor.cues.size()==cues,"client cannot broadcast authoritative falls");
 for(int deg=-720;deg<=720;deg+=3)for(boolean back:new boolean[]{false,true}){var d=Fall24.decode(Fall24.encode(deg,back));ok(d!=null&&Math.abs(Fall24.wrap(d.yaw()-deg))<.71&&d.back()==back,"direction protocol precision and front/back bit");}ok(Fall24.decode(999)==null&&Fall24.decode(1512)==null,"unrelated actions rejected");
 var guard=First24.frame(0,0,0,1);var jab=First24.frame(0,0,0,.25);var cover=First24.frame(0,1,0,.25);ok(jab.x()<guard.x()-.20&&jab.y()>guard.y()+.25&&jab.z()<guard.z()-.20,"jab moves from outside guard toward center and forward");ok(Math.abs(cover.x())>.25&&cover.y()<-.45,"opposite hand stays guarding");var heavy=First24.frame(1,0,0,.46);ok(heavy.x()<0&&heavy.wrist()>50,"heavy crosses center with wrist turn");
 var raised=Foot24.rig(.28,.7,.2,.08,1.6);var contact=Foot24.rig(.52,.7,.2,.08,1.6);ok(raised.ankle().y()-contact.ankle().y()>.30,"heel has clear vertical travel");ok(Math.abs(raised.ankle().z()-contact.ankle().z())<.02,"heel does not kick forward while descending");ok(raised.knee().x()>raised.ankle().x()+.25,"knee stays outside central view");ok(Math.abs(raised.pitch())<=6&&contact.pitch()==0,"flat sole at contact");
 FootPose footPose=new FootPose();var wearer=new StompChecks21.Equipped();Foot24.draw(new Object(),footPose,new StompChecks21.Buffer(),1,wearer,.52);ok(footPose.depth==0&&footPose.lastZ==1,"shoe toes face away from camera, with balanced pose");
 Pose pose=new Pose();long[]now={10_000_000_000L};BoxingClient16.CLOCK=()->now[0];Rise21.prone(b,pose);now[0]+=400_000_000L;Rise21.prone(b,new Pose());ok(Rise21.blend(Rise21.FALLS.get(b),now[0])==1,"front fall retains normal 9-second floor state");System.out.println("FIRST_PERSON_STANCE_FLAT_STOMP_AUTHORITATIVE_FRONT_BACK_SIDE_FALL_CHECKS="+checks);}
}
